// Benchmark: replay throughput (events/sec) on a synthetic capture file.
// The file is generated by tools/recorder (see docs/benchmarks/phase2.md).

#include <benchmark/benchmark.h>

#include <cstdint>
#include <string>
#include <vector>

#include "kairos/l2_book.hpp"
#include "kairos/replay.hpp"

namespace kairos {
namespace {

struct NullConsumer {
    void on_snapshot(std::uint64_t, std::uint64_t) {}
    void on_diff(std::uint64_t, std::uint64_t) {}
    void on_trade(std::uint64_t, std::uint64_t, std::int64_t, std::int64_t,
                  bool) {}
};

static void BM_ReplayThroughput(benchmark::State& state) {
    const char* path = std::getenv("KAIROS_BENCH_CAPTURE");
    if (!path) {
        state.SkipWithError("KAIROS_BENCH_CAPTURE not set");
        return;
    }
    const std::vector<std::string> paths = {path};
    // Warm up: count events once.
    std::uint64_t events = 0;
    std::uint64_t checksum_sink = 0;
    {
        data::CaptureReader r(paths);
        data::EventView ev;
        while (r.next(ev)) {
            ++events;
        }
    }
    for (auto _ : state) {
        ReplayEngine engine;
        NullConsumer c;
        const auto stats = engine.run(paths, c);
        // Prevent the run from being optimized away.
        benchmark::DoNotOptimize(checksum_sink += stats.checksum);
    }
    state.SetItemsProcessed(state.iterations() * events);
}

BENCHMARK(BM_ReplayThroughput)->Unit(benchmark::kMillisecond);

}  // namespace
}  // namespace kairos

BENCHMARK_MAIN();
